import {displayQuantity} from './adapter.js';
import {validAt,invoiceDetails} from './customer.js';
export const escapeText=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const e=escapeText,unknown='Not supplied';
const label=s=>s==null?unknown:String(s).replaceAll('_',' ');
const line=(key,v,mono=false)=>`<div class="detail-line"><span>${e(key)}</span><strong${mono?' class="mono"':''}>${e(v??unknown)}</strong></div>`;
const date=s=>s?String(s).slice(0,10):unknown;
const amount=(n,currency)=>{if(!Number.isFinite(n))return unknown;if(!currency)return n.toLocaleString('en-CA')+' (currency not supplied)';try{return new Intl.NumberFormat('en-CA',{style:'currency',currency}).format(n);}catch{return n+' '+currency;}};
const q=(v,unit,commodity)=>{if(!unit)return unknown;const out=displayQuantity(v,unit,commodity);return out.value==null?'Not received':out.value.toLocaleString('en-CA',{maximumFractionDigits:3})+' '+out.unit;};
const titles={electric:'Electricity',water:'Water',gas:'Gas'};
export function customerTabs(active){return `<nav class="profile-tabs" aria-label="Property details">${[['customer','Customer'],['service','Meters & service'],['billing','Billing']].map(([id,title])=>`<button data-profile-tab="${id}" aria-current="${active===id?'page':'false'}">${title}</button>`).join('')}</nav>`;}
export function profileHeader(p,mode){const h=p.home;return `<div class="eyebrow">CUSTOMER PROFILE · ${e(h.id)}</div><h2>${e(p.partner?.name||'Customer not supplied')}</h2><div class="profile-address">${e(h.address)}</div><div class="home-tags"><span>${mode==='demo'?'Fictional demo customer':'Engine customer records'}</span><span>${h.occupied===true?'Occupied':h.occupied===false?'Vacant':'Occupancy not supplied'}</span>${h.solar?'<span>Solar generation</span>':''}</div><button id="focus-home" class="outline-btn">Locate this property</button>`;}
export function customerMarkup(p,reads){
 const a=p.account,h=p.home;
 const services=p.services.map(s=>{
  const rs=reads.filter(r=>r.commodity===s.commodity).sort((a,b)=>String(b.periodEnd||'').localeCompare(String(a.periodEnd||'')));
  const latest=rs.find(r=>r.direction!=='export'),exp=rs.find(r=>r.direction==='export');
  const contract=s.contracts.find(c=>c.accountId===a?.id&&validAt(c,p.at));
  const meter=s.meters.find(({meter:m})=>(!m.installedAt||Date.parse(m.installedAt)<=Date.parse(p.at))&&(!m.removedAt||Date.parse(m.removedAt)>Date.parse(p.at)))?.meter;
  return `<section class="customer-service"><div class="service-card-head"><h3>${titles[s.commodity]}</h3><button data-service-detail="${s.commodity}" class="small-link">View meter</button></div>${line('Service',label(s.service?.status))}${line('Contract',contract?.id||'No active contract',true)}${line('Meter',meter?.serialNumber||meter?.id,true)}${line('Reading method',meter?.technology)}${line('Last consumption',latest?q(latest.consumption,latest.unit,s.commodity):'No readings supplied')}${exp?line('Export consumption',q(exp.consumption,exp.unit,s.commodity)):''}<p class="small-note">${latest?e(date(latest.periodStart)+' to '+date(latest.periodEnd)+' · '+label(latest.readStatus)):'Awaiting meter-read records.'}</p></section>`;
 }).join('');
 const activeContracts=p.contracts.filter(c=>c.accountId===a?.id&&validAt(c,p.at));
 return `<section class="detail-section"><h3>Account</h3>${line('Contract account',a?.id||h.accountId,true)}${line('Business partner',p.partner?.id||a?.businessPartnerId,true)}${line('Account relationship',activeContracts.length?'Current service contract':p.contracts.length?'Former / no active contract':unknown)}${line('Payment method',label(a?.paymentMethod))}${line('Budget billing',a?.budgetBilling===true?'Enrolled':a?.budgetBilling===false?'Not enrolled':unknown)}${line('Billing cycle',h.billingCycle??unknown)}${line('Currency',a?.currency)}${p.partner?.email?line('Email',p.partner.email):''}${p.partner?.phone?line('Phone',p.partner.phone):''}</section><section class="detail-section"><h3>Property & schedule</h3>${line('Premise',h.id,true)}${line('Building',h.buildingId,true)}${line('Occupants',h.occupied===false?'Vacant':h.occupants)}${line('Heating',h.heating_fuel||h.heatingFuel||(h.electricHeat?'Electric':unknown))}${line('Move-in',date(h.moveInAt||activeContracts[0]?.validFrom))}${line('Move-out',h.moveOutAt?date(h.moveOutAt):activeContracts.length?'No end date':unknown)}${line('Meter reading route',p.mru?.name||h.mruId)}${line('Route sequence',h.sequenceNo)}</section><section class="detail-section"><h3>Utility accounts</h3>${services}</section><details class="contract-history"><summary>Contract history · ${p.contracts.length}</summary>${p.contracts.map(c=>`<div class="history-row">${line('Contract',c.id,true)}${line('Account',c.accountId,true)}${line('Validity',date(c.validFrom)+' to '+(c.validTo?date(c.validTo):'open-ended'))}${line('At selected time',validAt(c,p.at)?'Within validity period':'Outside validity period')}</div>`).join('')||'<p class="small-note">No contracts supplied.</p>'}</details>`;
}
// Bills and invoices: an invoice's period comes from its billing documents; payments and dunning steps are dated; a
// bill built on an estimated read (and an invoice carrying one) is marked.
const steps=(title,rows,none)=>`<div class="billing-steps"><span>${e(title)}</span>${rows.length?`<ol>${rows.map(([d,t])=>`<li><time>${e(d)}</time> ${e(t)}</li>`).join('')}</ol>`:`<strong>${e(none)}</strong>`}</div>`;
const estimateTag=d=>d.estimated?'<span class="estimate-tag" title="Built on an estimated read">Estimated</span>':'';
export function billingMarkup(p,reads){
 const cur=d=>d.currency||p.account?.currency,period=d=>d.periodStart&&d.periodEnd?date(d.periodStart)+' to '+date(d.periodEnd):unknown;
 const bill=d=>`<article class="billing-record"><h4>${e(d.id)}${estimateTag(d)}</h4>${line('Status',label(d.billStatus??d.status))}${line('Period',period(d))}${line('Total',amount(d.totalAmount??d.total,cur(d)))}${d.reversedAt?line('Reversed',date(d.reversedAt)):''}${d.estimated?'<p class="small-note">Billed on an estimated read; the next actual read trues it up.</p>':''}</article>`;
 const invoice=v=>`<article class="billing-record"><h4>${e(v.id)}${estimateTag(v)}</h4>${line('Status',label(v.invoiceStatus??v.status))}${line('Period',period(v))}${line('Total',amount(v.totalAmount??v.total,cur(v)))}${v.issuedAt?line('Issued',date(v.issuedAt)):''}${v.dueAt?line('Due',date(v.dueAt)):''}${v.paidAt?line('Paid',date(v.paidAt)):''}${v.payments?steps('Payments',v.payments.map(x=>[date(x.at),amount(x.amount,cur(v))+(x.status?' · '+label(x.status):'')]),(v.totalAmount??0)<=0?'None due':'None yet'):''}${v.dunning?steps('Dunning',v.dunning.map(x=>[date(x.at),label(x.label||x.type)]),'None'):''}${v.estimated?'<p class="small-note">Includes a bill built on an estimated read.</p>':''}</article>`;
 const invoices=invoiceDetails(p.invoices,p.allBills||p.bills);
 const documents=(items,type)=>items.length?items.map(type==='bill'?bill:invoice).join(''):`<p class="billing-empty">No ${type==='bill'?'billing documents':'invoices'} supplied for this account.</p>`;
 const latest=new Map();for(const r of [...reads].sort((a,b)=>String(b.periodEnd||'').localeCompare(String(a.periodEnd||'')))){const key=r.registerId||r.commodity+':'+r.direction;if(!latest.has(key))latest.set(key,r);}
 return `<section class="detail-section"><h3>Meter-to-cash status</h3><p class="small-note">Reads and VEE remain separate from billing and invoicing.</p>${[...latest.values()].map(r=>`<article class="billing-record"><h4>${e(titles[r.commodity]||r.commodity)} · ${e(r.direction||'import')}</h4>${line('Read',label(r.readStatus))}${line('VEE',label(r.veeStatus))}${line('Bill status',label(r.billStatus))}${line('Invoice status',label(r.invoiceStatus))}</article>`).join('')||'<p class="billing-empty">No read records supplied.</p>'}</section><section class="detail-section"><h3>Account balance</h3>${line('Balance',amount(p.account?.balance,p.account?.currency))}<p class="small-note">Balances, charges and payments are shown only when supplied by the engine.</p></section><section class="detail-section"><h3>Billing documents · ${p.bills.length}</h3>${documents(p.bills,'bill')}</section><section class="detail-section"><h3>Invoices · ${invoices.length}</h3>${documents(invoices,'invoice')}</section>`;
}
export function meterMarkup(service,index,at){if(!service)return '';return `<section class="detail-section"><h3>Installed meter & registers</h3>${line('Installation',service.installation?.id,true)}${line('Read route',service.installation?.mruId)}${service.meters.map(({meter:m,registers})=>`<div class="billing-record">${line('Meter',m.id,true)}${line('Serial number',m.serialNumber,true)}${line('Technology',m.technology)}${line('Model',m.model)}${line('Installed',date(m.installedAt))}${line('Removed',m.removedAt?date(m.removedAt):'No removal recorded')}${line('Communications',label(m.commStatus))}${line('Multiplier',m.multiplier)}${registers.map(r=>line((r.direction==='export'?'Export':'Import')+' register',r.id+' · '+r.unit,true)).join('')}</div>`).join('')||'<p class="small-note">No meter record supplied.</p>'}${service.contracts.filter(c=>validAt(c,at)).flatMap(c=>(index.tariffsByContract.get(c.id)||[]).filter(t=>validAt(t,at))).map(t=>line('Rate assignment',t.tariffId+' · '+label(t.status))).join('')}</section>`;}
